    "exp1": "繰上げ受給とは、老齢基礎年金・老齢厚生年金を本来の65歳より前（60〜64歳）に受け取り始める制度。繰上げた月数×0.4%が年金額から減額され（2022年4月以降の新規裁定者）、その減額率は生涯にわたって変わらない。60歳0か月から繰り上げると最大24%（60か月×0.4%）の減額となる。62歳から繰り上げた場合は36か月×0.4%＝14.4%の減額。",
    "exp2": "試験では「減額率（0.4%/月）」「恒久的な減額」「繰上げ後は障害基礎年金を受け取れなくなる」の3点が頻出。計算例：60歳0か月で繰上げ→60か月×0.4%＝24%減額で生涯受給額が76%に。62歳で繰上げ→36か月×0.4%＝14.4%減額。繰上げ請求は老齢基礎年金と老齢厚生年金を同時に行う必要があり（片方だけ繰上げ不可）、請求後の取消も不可。損益分岐点は約80歳前後が目安。",
    "exp3": "繰上げ受給後は「障害基礎年金・寡婦年金を受け取れない」「国民年金への任意加入ができなくなる」などのデメリットがある。早期受給の魅力があるが、長生きするほど損になる点を理解しておく。繰上げ（0.4%/月減）vs 繰下げ（0.7%/月増）で数字が異なる点も混同しないこと。",
