    "exp2": "試験では「0.7%/月」「最大75歳まで」「増額率の計算」が頻出。計算例：70歳まで繰下げ→60か月×0.7%＝42%増、75歳まで→120か月×0.7%＝84%増。繰下げは老齢基礎年金・老齢厚生年金を別々に繰り下げることも可能（繰上げと異なる）。繰下げ待機中に他の年金（障害年金・遺族年金等）を受け取ると繰下げができなくなる点も出題される。2023年から「みなし繰下げ」制度で一括受取も可能になった。",
