    "exp1": "キャッシュフロー表とは、毎年の収入・支出・年間収支・累積貯蓄残高を時系列（通常10〜20年）で記入した表。将来の貯蓄残高を予測し、いつ資金不足になるかを把握するためのツール。残高は「前年末残高×（1＋運用利率）＋当年収支」で計算する（変動率を考慮した計算）。",
