    "exp2": "試験では「元利均等と元金均等の比較」が頻出。元利均等＝毎月返済額一定・総利息多め・初期負担軽い、元金均等＝当初返済額多い・総利息少ない・初期負担重い、が基本セット。計算例：3,000万円・30年・年1.5%で元利均等なら毎月返済約10.4万円で一定。元金均等なら初回返済約12.1万円（元金8.3万円＋初月利息3.75万円）で徐々に減少。「元利」の「利」は利息も含めた合計を均等にすると覚えると混同しない。",
