    "exp2": "「入院給付金の計算」は頻出。公式：受取額＝日額×（実入院日数−免責日数）。ただし（実入院日数−免責日数）が支払限度日数を超えた場合は上限で打ち切り。解法手順：①入院日数−免責日数＝給付日数（例：10日−3日＝7日）→②給付日数×日額＝受取額（例：7日×5,000円＝35,000円）→③支払限度日数（例：60日）を超えていないか確認（7日≦60日なので35,000円が受取額）。1回入院の上限（例：60日）と通算上限（例：730日）が別に設定されている商品も多い点も確認。",
