    "exp3": "複利は「雪だるま式に増える」イメージ。元本が大きいほど・期間が長いほど・利率が高いほど複利効果が大きくなる。単利との差は初期は小さいが、期間が長くなるにつれ急速に拡大する。「複利と単利の差は一定」は誤りで、時間とともに差が広がる点が複利の本質的な特徴。",
