    "exp1": "インフレ調整後利回り（実質利回り）とは、名目利回りから物価上昇率（インフレ率）を差し引いた、実質的な資産の増加率のこと。計算式は「実質利回り≒名目利回り−インフレ率」（厳密には(1＋名目利回り)÷(1＋インフレ率)−1）。名目利回りがプラスでもインフレ率の方が高ければ実質利回りはマイナスとなり、実質的な購買力が低下する。",
    "exp2": "「実質利回りの計算」は頻出。「名目利回り−インフレ率」の簡易計算式を使う問題が出る。例①：名目5%・インフレ率2%→実質利回り約3%（実質増加）。例②：名目2%・インフレ率2.5%→実質利回り約▲0.5%（実質目減り）。2026年現在の日本は物価上昇率が2〜3%台（2023年以降）に対し、普通預金金利は0.1〜0.2%台程度で実質的にマイナスになっているケースが多い。運用の目的は「インフレに勝つリターン」であることを意識する。",
    "exp3": "「金利がプラスだから資産は増えている」は不正確。インフレ率との比較が重要。預金金利0.1%・インフレ率2%なら実質▲1.9%で購買力は下がっている。この概念はiDeCoや投資信託の必要性を理解するための基礎知識。「名目利回りがプラスでも実質利回りはマイナスになりえる」という直感と逆の理解が試験で問われる。",
    "memory": "実質利回り＝「**名目−インフレ率**」。物価が上がる以上に増やせなきゃ実質は目減り。預金0.1%vsインフレ2%は実質マイナス。",
