    "exp2": "「債券と株式の違い」は頻出。債券の特徴：確定利息（クーポン）・満期に額面金額（元本）返還・議決権なし・倒産時の弁済は株主より優先（担保付社債＞無担保社債＞株主）。株式の特徴：配当は不確定（業績依存）・元本保証なし・議決権あり・価格変動が大きい。安定した利息収入・資産保全を求める場合は債券、成長による値上がり益・高配当を求める場合は株式、という使い分けが基本。「債券保有者は会社のオーナー」は誤りで、株主がオーナー。",
