    "exp2": "「社債と国債の比較」が頻出。比較表：安全性は国債＞社債、利回りは社債＞国債、信用リスクは国債が実質ゼロ・社債は発行会社の信用力に依存。倒産時の弁済順位：担保付社債＞無担保社債＞株主。格付けと利回りの関係：格付けが高い（AAA・AA等）→信用リスク低い→利回りは低い。格付けが低い（BB以下のハイイールド）→信用リスク高い→利回りは高い。「利回りが高い＝リスクが高い」というトレードオフを理解する。",
    "exp3": "社債は株式と混同されやすいが別物。社債保有者は「債権者」で議決権なし・利息と元本の返済請求権あり。株式保有者は「株主」で議決権あり・配当は不確定・倒産時の弁済は社債より後回し。「社債を買えば会社の経営に参加できる」は誤りで、社債は純粋な貸し付け（債権）。",
    "memory": "社債＝「**会社にお金を貸す**（利回り↑信用リスク↑）」。国債より高利回り、その分倒産リスクあり。格付けBBB以上が投資適格。"
