    "exp2": "「デュレーションと金利リスクの関係」は頻出。デュレーションが長い→金利変動への感応度が高い→金利1%変動で価格変動が大きい（例：デュレーション5年の債券は金利1%上昇で価格約5%下落）。デュレーションが長くなる条件：残存期間が長い・クーポン（利率）が低い・ゼロクーポン債。デュレーションが短くなる条件：残存期間が短い・高利回り（クーポンが高い）・短期債。金利上昇リスクを避けたい場合はデュレーションの短い債券を選ぶという実務的判断にもつながる。",
