    "exp1": "ROE（Return On Equity：自己資本利益率）は、当期純利益を自己資本（純資産）で割った指標で、株主の投資に対する収益効率を示す。計算式：ROE（%）＝当期純利益÷自己資本×100。ROEが高いほど株主資本を効率よく使って利益を生み出している優良企業と評価される。日本企業のROEは欧米企業と比べて低いとされ、改善が課題とされてきた。",
    "exp2": "「ROEの計算と意味」が頻出計算問題。計算：ROE（%）＝当期純利益÷自己資本×100。例：純利益60億円・自己資本300億円→ROE＝20%。「株主が100円投資して20円の利益を生み出した」という意味。日本企業のROEは2000年代は5〜8%程度と低く、コーポレートガバナンス改革（2015〜）以降で改善傾向。東証の要請もあり、2026年現在は10%以上を目安とする企業が増加。同業種での比較や、PER・PBRと組み合わせて総合的に評価するのが実務的。",
    "exp3": "ROEとROAを混同しやすい。ROE＝純利益÷自己資本（株主目線の指標・株主の投資効率）、ROA＝純利益÷総資産（経営全体の資産効率）。ROEは借入を増やす（財務レバレッジを高める）だけでも数値が上がるため、高ROEが必ずしも健全経営を意味しない点に注意。「ROEとROAの分母の違い（自己資本vs総資産）」が試験のひっかけポイント。",
    "memory": "RO**E**＝「**E**quity（自己資本）で割る」・RO**A**＝「**A**sset（総資産）で割る」。Eは株主目線・Aは経営全体目線。10%以上が優良ライン。",
    "svg": "<svg width=\"300\" height=\"165\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect x=\"10\" y=\"10\" width=\"280\" height=\"150\" rx=\"8\" fill=\"#f0fdf4\" stroke=\"#16a34a\" stroke-width=\"1.5\"/>\n  <text x=\"150\" y=\"30\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#166534\">ROE = 当期純利益 ÷ 自己資本 × 100</text>\n  <text x=\"20\" y=\"52\" font-size=\"11\" fill=\"#374151\">例：純利益60億円 ÷ 自己資本300億円 × 100</text>\n  <rect x=\"20\" y=\"60\" width=\"260\" height=\"22\" rx=\"4\" fill=\"#dcfce7\" stroke=\"#16a34a\"/>\n  <text x=\"150\" y=\"75\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#166534\">ROE = 20%</text>\n  <line x1=\"20\" y1=\"92\" x2=\"280\" y2=\"92\" stroke=\"#86efac\" stroke-width=\"1\"/>\n  <text x=\"20\" y=\"110\" font-size=\"10\" fill=\"#374151\">ROE高い → 株主資本を効率よく活用</text>\n  <text x=\"20\" y=\"126\" font-size=\"10\" fill=\"#374151\">ROE低い → 株主資本の活用が非効率</text>\n  <text x=\"20\" y=\"150\" font-size=\"9\" fill=\"#6b7280\">ROE vs ROA：ROEは自己資本、ROAは総資産が分母</text>\n</svg>"
