    "exp2": "「誰が・何%・何の税に使うか」の3点が試験出題の軸。市区町村・70%・固定資産税/都市計画税。相続税路線価（国税庁・80%）との混同に注意。固定資産税評価額は所有者に届く「課税明細書」で確認できる。3年ごとの評価替えで改定されるため、直近の地価動向と乖離する場合がある点も実務では重要。固定資産税評価額は「不動産取得税・登録免許税・固定資産税・都市計画税」の4税の計算基礎となる（相続税路線価より使用範囲が広い）。",
