    "exp1": "不動産の取得費とは、購入代金に加えて購入時にかかった諸費用（仲介手数料・登記費用・印紙税等）の合計。建物の場合は取得費から減価償却費相当額を差し引いて計算する。取得費が不明または実際の取得費が売却価格の5%未満の場合は、売却価格×5%を「概算取得費」として使うことができる。",
    "exp2": "計算問題では「取得費をどう計算するか」が重要。実際の取得費が判明している場合は実額を使う。不明な場合は5%概算。たとえば3,000万円で売却した場合の概算取得費は150万円（3,000万×5%）→譲渡所得＝3,000万−150万−譲渡費用。建物部分の減価償却費相当額（定額法）を取得費から差し引く計算も重要：木造（耐用年数22年）・RC（47年）の減価償却率で計算した累計額が控除される。",
    "exp3": "「取得費不明＝譲渡所得が売却価格全額になる」は誤り。5%の概算取得費が使える。一方、実際の取得費が判明していて5%より大きければ実額を使う方が有利（譲渡所得を小さくできる）。相続・贈与で取得した不動産の取得費は「被相続人・贈与者の購入時の取得費を引き継ぐ（引継ぎ取得費）」点も重要。",
    "memory": "書類あれば実額・なければ売値の5%概算・相続は被相続人の取得費をそのまま引継ぐ。",
