    "exp1": "譲渡費用とは、不動産を売るために直接かかった費用のこと。譲渡所得の計算で売却価格から差し引くことができる。含まれるもの：仲介手数料・売買契約書の印紙税・測量費・境界確定費用・売却のための解体費・立退料など。含まれないもの：取得後の修繕費・管理費・固定資産税・ローンの利子（取得費に算入できる例外あり）。",
    "exp2": "「譲渡費用に含まれるかどうか」は試験で選択肢として出る。判断基準は「売却するために直接必要だったかどうか」。修繕費は「所有のための費用」であり、売却の直接費用ではないため譲渡費用にならない。計算式：譲渡所得＝売却価格－（取得費＋譲渡費用）。不動産売却の仲介手数料：売却価格×3%＋6万円＋消費税（売却価格400万円超の場合）が上限。1億円売却なら仲介手数料最大（1億×3%＋6万）×1.1＝333.3万円程度。この全額が譲渡費用として控除可能。",
    "exp3": "「固定資産税＝譲渡費用」と思いがちだが、固定資産税は所有に伴うコストで売却のための費用ではないため譲渡費用に含まれない。解体費も「売るために建物を壊した（更地にして売却）」場合は含まれるが、単なる老朽化対応の解体は含まれないケースがある。「売却目的」かどうかが判断の軸。",
    "memory": "譲渡費用は「売るために直接かかった費用」。仲介手数料・測量費・解体費はOK。修繕費・固定資産税はNG。売却目的か否かが判断軸。",
    "svg": "<svg width=\"300\" height=\"155\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"155\" fill=\"#fff8e1\" rx=\"8\"/>\n  <text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#e65100\">譲渡費用の該当・非該当</text>\n  <rect x=\"10\" y=\"30\" width=\"135\" height=\"110\" fill=\"#ffe0b2\" rx=\"5\"/>\n  <rect x=\"155\" y=\"30\" width=\"135\" height=\"110\" fill=\"#f5f5f5\" rx=\"5\"/>\n  <text x=\"77\" y=\"50\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"bold\" fill=\"#e65100\">✅ 含まれる</text>\n  <text x=\"77\" y=\"66\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">仲介手数料</text>\n  <text x=\"77\" y=\"80\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">印紙税（売買契約書）</text>\n  <text x=\"77\" y=\"94\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">測量費・境界確定費</text>\n  <text x=\"77\" y=\"108\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">売却のための解体費</text>\n  <text x=\"77\" y=\"122\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">立退料</text>\n  <text x=\"222\" y=\"50\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"bold\" fill=\"#757575\">❌ 含まれない</text>\n  <text x=\"222\" y=\"66\" text-anchor=\"middle\" font-size=\"9\" fill=\"#555\">修繕費・管理費</text>\n  <text x=\"222\" y=\"80\" text-anchor=\"middle\" font-size=\"9\" fill=\"#555\">固定資産税</text>\n  <text x=\"222\" y=\"94\" text-anchor=\"middle\" font-size=\"9\" fill=\"#555\">ローン返済額・利子</text>\n  <text x=\"222\" y=\"108\" text-anchor=\"middle\" font-size=\"9\" fill=\"#555\">老朽化対応の解体費</text>\n</svg>"
