    "exp2": "借地権と借家権の違いが試験頻出。借地権＝土地を借りて建物を建てる権利（土地が対象）、借家権＝建物を借りる権利（建物が対象）。相続税評価での数値：借地権評価額＝自用地評価額×借地権割合。路線価図に借地権割合（A70%〜G30%）が記載されており、都市部ほど高い。底地評価額＝自用地評価額×（1－借地権割合）。例：自用地1億円・借地権割合70%なら、借地権7,000万円・底地3,000万円。",
    "exp3": "借地権は土地の賃借人が「土地を使う権利」。地主から見ると「底地（借地権が設定された土地）」として評価が下がる。借地権者は地代を払うが、建物の所有権は借地権者にある。一般定期借地権（50年以上）や事業用定期借地権（10〜50年未満）は期間満了で返還されるが、旧借地法の普通借地権は正当事由なく解約できない強い保護がある。",
    "memory": "借地権は建物所有目的で他人の土地を借りる権利。評価額＝自用地×借地権割合（A70%〜G30%）。底地＝自用地×（1－借地権割合）。"
