    "scenario": "不動産オーナーの自分が所有する土地を50年の一般定期借地権で貸し出した。通常の借地権と違い、期間満了後は確実に土地が戻ってくる仕組みに安心した。",
    "q": "次の状況に当てはまるのは？",
