    "exp1": "借家権は建物（家屋）を借りる権利で、借地借家法によって強く保護されている。貸主（大家）が契約を解約・更新拒絶するには正当事由が必要で、「自分で使いたい」「老朽化した建物を取り壊したい」などの理由が認められる場合がある。借主（入居者）からは比較的自由に解約できる（一般的に1か月前通知）。",
