    "exp1": "農地法は農地の権利移動・転用を規制し、食料生産の基盤となる農地を守るための法律。主な条文：3条許可（農地のままで売買・贈与・貸借→農業委員会の許可）、4条許可（自分の農地を農地以外に転用→都道府県知事等の許可）、5条許可（農地を転用目的で売買・貸借→都道府県知事等の許可）。相続による農地取得は許可不要だが、取得後に農業委員会への届出が必要。",
    "exp2": "「3条・4条・5条」の区別が試験頻出。農地法3条：農地のまま権利移動（売買・貸借）→農業委員会の許可。農地法4条：自分の農地を農地以外に転用（農家が自分で転用）→都道府県知事等の許可。農地法5条：農地を転用目的で権利移動（転用予定で売買・貸借）→都道府県知事等の許可。市街化区域内農地の転用：農業委員会への「届出」のみでよい（4条・5条の許可不要）という特例も覚える。",
    "exp3": "「相続した農地だから自由に処分できる」は誤り。相続取得は農地法の許可不要（3条の例外）だが、相続後に売却（3条）・転用（4条）・転用目的の売却（5条）をするには許可が必要。また相続後は農業委員会への届出が義務（農地法3条の3）。農地法違反には罰則（3年以下の懲役または300万円以下の罰金）がある。",
    "memory": "農地法3条＝農地のまま売買は農業委員会、4条＝自分で転用・5条＝転用目的売買は知事許可。相続取得は許可不要で届出のみ。"
