    "exp2": "「土地活用の目的・リスク・向いている人」の組合せが試験ポイント。①等価交換：自己資金不要・建物持分取得・土地の一部を失う。②定期借地権（事業用10〜50年）：建物所有リスクなし・地代収入・土地は最終的に返還。③賃貸経営：収益性最大・建築資金・空室リスク・管理コスト必要。税務上：賃貸用建物があると固定資産税の住宅用地特例（1/6〜1/3減額）・相続税評価の貸家建付地評価減・小規模宅地等特例が使える。",
