    "exp1": "不動産投資は不動産を取得して①賃料収入（インカムゲイン）と②不動産価格の上昇による売却益（キャピタルゲイン）を得ることを目的とする投資手法。主なリスクは空室リスク・家賃下落リスク・金利上昇リスク・流動性リスク（すぐに売れない）・修繕リスクなど。投資判断には利回り（表面・実質）の計算が基本となる。",
    "exp2": "不動産投資のリスクが試験頻出。主なリスク：①空室リスク（入居者がいない期間は収入ゼロ）②家賃下落リスク（築年数経過や地域の需要変化）③金利上昇リスク（変動金利ローンの返済増加）④流動性リスク（株と異なりすぐに売れない）⑤修繕リスク（予期せぬ修繕費発生）。REITは不動産投資を小口化・証券化したもので、1口数万円から投資でき証券取引所で売買できる（流動性リスクが低い）。",
    "exp3": "「利回りが高い＝良い物件」は単純すぎる。表面利回り10%の物件が実際に空室続きで年間実収入がゼロになるケースもある。リスクとのトレードオフ：高利回り＝高リスク（築古・地方・空室率高）、低利回り＝低リスク（都心・新築・安定）。不動産投資の判断には表面利回り・実質利回り・空室率・立地・築年数・修繕履歴を総合評価する必要がある。",
    "memory": "不動産投資の収益＝「**インカム（賃料）＋キャピタル（売却益）**」の二刀流。5大リスク＝空室・家賃下落・金利上昇・流動性・修繕。\n\n<svg width=\"300\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"150\" fill=\"#e0f2f1\" rx=\"8\"/>\n  <text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#004d40\">不動産投資の収益源</text>\n  <rect x=\"20\" y=\"30\" width=\"120\" height=\"80\" fill=\"#80cbc4\" rx=\"5\"/>\n  <rect x=\"160\" y=\"30\" width=\"120\" height=\"80\" fill=\"#a5d6a7\" rx=\"5\"/>\n  <text x=\"80\" y=\"55\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"bold\" fill=\"#004d40\">インカムゲイン</text>\n  <text x=\"80\" y=\"72\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">賃料収入</text>\n  <text x=\"80\" y=\"86\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">毎月・定期的</text>\n  <text x=\"220\" y=\"55\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"bold\" fill=\"#1b5e20\">キャピタルゲイン</text>\n  <text x=\"220\" y=\"72\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">売却益（値上がり益）</text>\n  <text x=\"220\" y=\"86\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">売却時に一度</text>\n  <text x=\"150\" y=\"130\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">空室リスク・流動性リスクに注意</text>\n</svg>",
    "svg": "<svg width=\"300\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"150\" fill=\"#e0f2f1\" rx=\"8\"/>\n  <text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#004d40\">不動産投資の収益源</text>\n  <rect x=\"20\" y=\"30\" width=\"120\" height=\"80\" fill=\"#80cbc4\" rx=\"5\"/>\n  <rect x=\"160\" y=\"30\" width=\"120\" height=\"80\" fill=\"#a5d6a7\" rx=\"5\"/>\n  <text x=\"80\" y=\"55\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"bold\" fill=\"#004d40\">インカムゲイン</text>\n  <text x=\"80\" y=\"72\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">賃料収入</text>\n  <text x=\"80\" y=\"86\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">毎月・定期的</text>\n  <text x=\"220\" y=\"55\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"bold\" fill=\"#1b5e20\">キャピタルゲイン</text>\n  <text x=\"220\" y=\"72\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">売却益（値上がり益）</text>\n  <text x=\"220\" y=\"86\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">売却時に一度</text>\n  <text x=\"150\" y=\"130\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">空室リスク・流動性リスクに注意</text>\n</svg>"
