    "exp1": "倍率方式は、路線価が設定されていない地域（農村部・郊外など）の宅地評価に使う方法。評価額＝固定資産税評価額×国税局長が定める倍率。倍率は国税庁の「評価倍率表」で地域・地目ごとに確認できる。例：固定資産税評価額800万円×倍率1.1＝880万円が相続税評価額。\n\n<svg width=\"300\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"150\" fill=\"#f0f7e6\" rx=\"8\"/>\n  <text x=\"150\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#2d6a2d\">倍率方式の計算</text>\n  <rect x=\"20\" y=\"35\" width=\"260\" height=\"30\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1b5e20\">固定資産税評価額 × 倍率（評価倍率表）</text>\n  <text x=\"30\" y=\"85\" font-size=\"11\" fill=\"#333\">例）固定資産税評価額 800万円</text>\n  <text x=\"30\" y=\"103\" font-size=\"11\" fill=\"#333\">　　倍率 1.1（評価倍率表より）</text>\n  <line x1=\"20\" y1=\"112\" x2=\"280\" y2=\"112\" stroke=\"#4caf50\" stroke-width=\"1.5\"/>\n  <text x=\"30\" y=\"133\" font-size=\"12\" font-weight=\"bold\" fill=\"#1b5e20\">評価額 ＝ 800万円 × 1.1</text>\n  <text x=\"30\" y=\"148\" font-size=\"12\" font-weight=\"bold\" fill=\"#d32f2f\">　　　 ＝ 880万円</text>\n</svg>",
    "exp2": "試験では「路線価方式と倍率方式の使い分け（路線価設定地域か否か）」「倍率方式の計算式（固定資産税評価額×倍率）」が問われる。路線価が設定されている地域は路線価方式が優先。農地・山林などは倍率方式が多く使われる。倍率は国税庁が公表する「評価倍率表」で地域・地目ごとに確認でき、1.0〜数倍の幅がある。固定資産税評価額は3年ごとに見直しされるため、最新年度のものを使う点も実務では重要。",
    "exp3": "「倍率方式＝公示価格×倍率」は誤り。正しくは固定資産税評価額×倍率。固定資産税評価額は市区町村が決定し、公示価格の約70%水準が目安とされる。路線価方式が「路線価（国税庁）×補正率×地積」、倍率方式が「固定資産税評価額（市区町村）×倍率（国税局）」——使う数値の出どころが異なる点で区別する。",
    "memory": "倍率方式は路線価なし地域（農村・郊外）に適用。評価額＝固定資産税評価額×評価倍率表の倍率。「公示価格×倍率」は誤り。路線価は国税庁、固定資産税評価額は市区町村——出どころで2方式を区別する。",
    "svg": "<svg width=\"300\" height=\"150\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"150\" fill=\"#f0f7e6\" rx=\"8\"/>\n  <text x=\"150\" y=\"22\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"bold\" fill=\"#2d6a2d\">倍率方式の計算</text>\n  <rect x=\"20\" y=\"35\" width=\"260\" height=\"30\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"55\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1b5e20\">固定資産税評価額 × 倍率（評価倍率表）</text>\n  <text x=\"30\" y=\"85\" font-size=\"11\" fill=\"#333\">例）固定資産税評価額 800万円</text>\n  <text x=\"30\" y=\"103\" font-size=\"11\" fill=\"#333\">　　倍率 1.1（評価倍率表より）</text>\n  <line x1=\"20\" y1=\"112\" x2=\"280\" y2=\"112\" stroke=\"#4caf50\" stroke-width=\"1.5\"/>\n  <text x=\"30\" y=\"133\" font-size=\"12\" font-weight=\"bold\" fill=\"#1b5e20\">評価額 ＝ 800万円 × 1.1</text>\n  <text x=\"30\" y=\"148\" font-size=\"12\" font-weight=\"bold\" fill=\"#d32f2f\">　　　 ＝ 880万円</text>\n</svg>"
