    "exp1": "都市計画区域は都市計画法に基づく区域。内部は大きく3つに区分される。①市街化区域：すでに市街化されているか、今後10年以内に優先的に市街化を進める区域。用途地域が指定される。②市街化調整区域：市街化を抑制する区域。原則として開発・建築が厳しく制限。③非線引き区域（区域区分非設定）：市街化区域・調整区域に区分されていない区域。",
    "exp2": "試験では「市街化区域と市街化調整区域の違い」「市街化調整区域での建築制限」「用途地域が指定されるのは市街化区域」が問われる。市街化調整区域では農地転用も厳しく規制され、農業・林業等に関する建築物に限定される場合が多い。用途地域は市街化区域内に13種類（第一種低層住居専用地域〜工業専用地域）が設定され、建てられる建物の種類・容積率・建蔽率等を規制する。市街化区域は「すでに市街化されているか10年以内に優先的に整備する区域」という定義も頻出。",
    "exp3": "「都市計画区域外は何を建ててもよい」は誤り。都市計画区域外でも建築確認が必要な場合があり、一定の建築制限がある。また準都市計画区域という概念も存在する。市街化区域（建てOK）と市街化調整区域（原則建て禁止）を「推進と抑制」で対比して覚える——「市街化」という同じ言葉が入っているため、「調整＝抑制」というキーワードで区別する。",
    "memory": "都市計画区域は「推進・抑制・中間」の3区分。市街化区域は建築OK＆用途地域あり、市街化調整区域は原則建築禁止。「調整＝抑制」で区別し、用途地域13種は市街化区域にのみ設定。"
