    "exp2": "試験では「開発許可が必要な面積の基準（市街化区域1,000㎡）」「市街化調整区域は原則全件許可必要」「農林漁業目的の開発は許可不要な場合あり」が問われる。開発許可を受けた開発区域内では、工事完了公告前は建築物を建ててはならない。許可不要の例外として農林漁業目的・一定の公益施設・駅舎等のほか、非常災害に対応した応急措置も許可不要。市街化区域の1,000㎡基準は三大都市圏の特定区域では500㎡に引き下げられている点も試験頻出。",
