    "exp2": "試験では「農地法3条（権利移動）・4条（転用）・5条（権利移動＋転用）の違い」が問われる。3条は農地のまま売買・賃借する場合、4条は自分が転用する場合、5条は売買・賃借しつつ転用する場合。4条と5条で転用可否が変わるのは「権利移動を伴うか否か」。許可権者は原則「農業委員会」だが、4ヘクタール超の農地転用は農林水産大臣の許可が必要（2023年以降は都道府県知事経由で農林水産大臣の許可）。市街化区域内の農地は3条（権利移動）は農業委員会の許可が必要だが、4条・5条（転用）は届出のみでよい点がポイント。",
    "exp3": "「市街化区域内の農地なら転用が自由」は誤り。市街化区域内の農地は農業委員会への届出で転用できる（許可不要）が、届出自体は必要。「許可不要＝手続き不要」と混同しない。農地法3条（売買）・4条（自己転用）・5条（売買＋転用）の区別：「誰が何をするか」で番号を振り分ける——3条は「農地のまま動かす」、4条は「自分が転用」、5条は「動かしながら転用」と動詞で覚える。",
