    "exp1": "相続とは、被相続人（亡くなった人）の財産・権利義務を相続人が承継すること。承継される財産にはプラスの財産（現預金・不動産・株式等）だけでなく、マイナスの財産（借入金・未払税金・連帯保証債務等）も含まれる。相続人は「単純承認」「限定承認」「相続放棄」の3つから選択できる。",
    "exp2": "試験では「相続の対象（プラス・マイナス両方）」「承認・放棄の種類と期限（3か月以内）」「相続開始の原因（死亡・失踪宣告）」が問われる。法定相続と遺言による相続があり、遺言がある場合は原則遺言が優先。ただし遺留分の侵害には遺留分侵害額請求が可能。相続開始の原因は「死亡」のほかに「失踪宣告（普通失踪：7年不在、危難失踪：1年不在で死亡とみなす）」もある。単純承認・限定承認・相続放棄の選択期限はいずれも「相続の開始を知った日から3か月以内」——被相続人の死亡日からではない点に注意。",
    "exp3": "「相続放棄すればマイナスだけ捨てられる」は誤り。相続放棄は全ての財産（プラスもマイナスも）を放棄すること。プラスだけ受け取ってマイナスを拒否することは単純承認では不可能。「マイナスだけ排除・プラスだけ取る」という都合のいい方法は存在しない——それをしたいなら「限定承認（全員合意が必要）」で財産の範囲内でのみ負債を承継するしかない。",
    "memory": "相続はプラスもマイナスも全承継。放棄は全捨て・単純承認は全受け・限定承認は財産の範囲内で負債承継。選択期限は「相続開始を知った日から3か月以内」、死亡日からではない。"
