    "exp1": "相続税は、被相続人の死亡によって相続・遺贈・死因贈与で財産を取得した者に課される国税。相続財産の総額から基礎控除（3,000万円＋600万円×法定相続人数）を差し引いた残額に課税。法定相続分で按分した後、各人の取得額に応じた税額を計算する超過累進課税。財産の取得時点（相続開始日）の評価額で課税される。",
    "exp2": "試験では「相続税は国税か地方税か（国税）」「課税タイミング（取得時）」「基礎控除の計算式」「申告期限（相続開始を知った日の翌日から10か月以内）」が問われる。相続税の申告・納付は金銭一括納付が原則だが、延納・物納の制度もある。2026年現在の相続税の最高税率は55%（課税遺産総額6億円超の部分）。相続税の課税対象者は全相続・遺贈取得者のうち、遺産総額が基礎控除を超えた場合に限られ、実際に申告が必要な相続は全相続件数の約9〜10%程度（2023年度統計）。基礎控除が2015年に大幅縮小（5,000万円＋1,000万円×人数→3,000万円＋600万円×人数）されたことで課税対象が増加した。\n\n<svg width=\"300\" height=\"155\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"155\" fill=\"#f0f7e6\" rx=\"8\"/>\n  <text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2d6a2d\">相続税の課税フロー（概要）</text>\n  <rect x=\"15\" y=\"28\" width=\"270\" height=\"22\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"43\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">遺産総額 − 基礎控除 ＝ 課税遺産総額</text>\n  <text x=\"150\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">基礎控除：3,000万円＋600万円×法定相続人数</text>\n  <text x=\"150\" y=\"78\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">（法定相続人3人の場合：4,800万円）</text>\n  <line x1=\"15\" y1=\"86\" x2=\"285\" y2=\"86\" stroke=\"#4caf50\" stroke-width=\"1.5\"/>\n  <text x=\"20\" y=\"103\" font-size=\"10\" fill=\"#333\">例）遺産総額1億2,000万円 − 4,800万円</text>\n  <text x=\"20\" y=\"119\" font-size=\"11\" font-weight=\"bold\" fill=\"#1b5e20\">課税遺産総額 ＝ 7,200万円</text>\n  <text x=\"20\" y=\"137\" font-size=\"9\" fill=\"#555\">申告期限：相続開始を知った日の翌日から10か月以内</text>\n</svg>",
    "exp3": "「相続した財産を売ったときに相続税がかかる」は誤り。相続税は財産を「取得した時点」で課税。売却したときは別途「譲渡所得税」が課税される。相続と売却は別々の課税イベント。",
    "memory": "相続税は「取得時点」に課す国税。基礎控除超過分に10〜55%超過累進課税。申告期限は相続開始を知った日の翌日から10か月以内。売却時は別途譲渡所得税。",
    "svg": "<svg width=\"300\" height=\"155\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"155\" fill=\"#f0f7e6\" rx=\"8\"/>\n  <text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2d6a2d\">相続税の課税フロー（概要）</text>\n  <rect x=\"15\" y=\"28\" width=\"270\" height=\"22\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"43\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">遺産総額 − 基礎控除 ＝ 課税遺産総額</text>\n  <text x=\"150\" y=\"62\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">基礎控除：3,000万円＋600万円×法定相続人数</text>\n  <text x=\"150\" y=\"78\" text-anchor=\"middle\" font-size=\"10\" fill=\"#555\">（法定相続人3人の場合：4,800万円）</text>\n  <line x1=\"15\" y1=\"86\" x2=\"285\" y2=\"86\" stroke=\"#4caf50\" stroke-width=\"1.5\"/>\n  <text x=\"20\" y=\"103\" font-size=\"10\" fill=\"#333\">例）遺産総額1億2,000万円 − 4,800万円</text>\n  <text x=\"20\" y=\"119\" font-size=\"11\" font-weight=\"bold\" fill=\"#1b5e20\">課税遺産総額 ＝ 7,200万円</text>\n  <text x=\"20\" y=\"137\" font-size=\"9\" fill=\"#555\">申告期限：相続開始を知った日の翌日から10か月以内</text>\n</svg>"
