    "exp1": "相続税の基礎控除額＝3,000万円＋600万円×法定相続人の数。法定相続人が3人の場合：3,000万円＋600万円×3＝4,800万円。遺産総額8,000万円の場合、課税遺産総額＝8,000万円－4,800万円＝3,200万円。基礎控除以下なら相続税はゼロ（申告不要）。相続放棄した人も法定相続人の数には含めてカウントする。\n\n<svg width=\"300\" height=\"160\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"160\" fill=\"#f0f7e6\" rx=\"8\"/>\n  <text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2d6a2d\">相続税の基礎控除額</text>\n  <rect x=\"15\" y=\"28\" width=\"270\" height=\"28\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"44\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1b5e20\">3,000万円 ＋ 600万円 × 法定相続人の数</text>\n  <text x=\"20\" y=\"72\" font-size=\"11\" fill=\"#333\">例）法定相続人3人（配偶者・子2人）</text>\n  <text x=\"20\" y=\"89\" font-size=\"11\" fill=\"#333\">　3,000万円＋600万円×3＝4,800万円</text>\n  <line x1=\"15\" y1=\"97\" x2=\"285\" y2=\"97\" stroke=\"#4caf50\" stroke-width=\"1.5\"/>\n  <text x=\"20\" y=\"115\" font-size=\"11\" fill=\"#333\">遺産総額8,000万円 − 基礎控除4,800万円</text>\n  <text x=\"20\" y=\"133\" font-size=\"12\" font-weight=\"bold\" fill=\"#d32f2f\">課税遺産総額 ＝ 3,200万円</text>\n  <text x=\"20\" y=\"152\" font-size=\"9\" fill=\"#555\">※相続放棄者もカウント対象</text>\n</svg>",
    "exp2": "試験では「基礎控除の計算式（3,000万円＋600万円×人数）」「相続放棄者も人数に含める」「孫養子の場合の人数制限（実子がいれば1人まで、いなければ2人まで）」が問われる。基礎控除以下であれば申告不要（ただし配偶者の税額軽減・小規模宅地特例を使う場合は申告必須）。法定相続人が多いほど基礎控除が増えて有利になるため、養子縁組が節税策として活用されることがあるが、この無制限活用を防ぐため上記の人数制限が設けられている。相続人数が4人なら基礎控除は3,000万円＋600万円×4＝5,400万円となる。",
    "exp3": "旧制度（2014年以前）の「5,000万円＋1,000万円×人数」と混同しやすい。現行（2015年以降）は3,000万円＋600万円×人数。2015年の改正で引き下げられ、課税対象となる相続が大幅に増えた。「3000・600」を「3と6」のペアで覚える——旧制度の「5000・1000」（5と10）とは倍率関係がないため、現行の数字を上書きで暗記する。",
    "memory": "基礎控除の合言葉は「3000と600」。3,000万円＋600万円×法定相続人数。相続放棄者も人数にカウント。旧制度「5000・1000」と混同厳禁。",
    "svg": "<svg width=\"300\" height=\"160\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"160\" fill=\"#f0f7e6\" rx=\"8\"/>\n  <text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2d6a2d\">相続税の基礎控除額</text>\n  <rect x=\"15\" y=\"28\" width=\"270\" height=\"28\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"44\" text-anchor=\"middle\" font-size=\"12\" fill=\"#1b5e20\">3,000万円 ＋ 600万円 × 法定相続人の数</text>\n  <text x=\"20\" y=\"72\" font-size=\"11\" fill=\"#333\">例）法定相続人3人（配偶者・子2人）</text>\n  <text x=\"20\" y=\"89\" font-size=\"11\" fill=\"#333\">　3,000万円＋600万円×3＝4,800万円</text>\n  <line x1=\"15\" y1=\"97\" x2=\"285\" y2=\"97\" stroke=\"#4caf50\" stroke-width=\"1.5\"/>\n  <text x=\"20\" y=\"115\" font-size=\"11\" fill=\"#333\">遺産総額8,000万円 − 基礎控除4,800万円</text>\n  <text x=\"20\" y=\"133\" font-size=\"12\" font-weight=\"bold\" fill=\"#d32f2f\">課税遺産総額 ＝ 3,200万円</text>\n  <text x=\"20\" y=\"152\" font-size=\"9\" fill=\"#555\">※相続放棄者もカウント対象</text>\n</svg>"
