    "exp1": "相続税の債務控除の対象となる葬式費用：通夜・告別式費用、火葬・納骨費用、お布施・戒名料（社会的に相当な範囲）、死体の搬送費用など。控除できない費用：香典返し費用、墓石・墓地の購入費（非課税財産のため別扱い）、初七日・四十九日等の法事費用、遺言執行費用。上記の例では150万円＋30万円＝180万円が控除可。",
