    "exp3": "「葬式に払ったお金は全部控除できる」は誤り。香典返し・墓石・法事費用（初七日・四十九日等）は控除不可。葬儀関連費用のうち「通夜・告別式・火葬・搬送に直接関わるもの」だけが控除対象と覚える。",
    "memory": "通夜・告別式・火葬・納骨は控除OK。香典返し・墓石・初七日以降の法事費用はNG。「葬儀当日に直接かかる費用だけ」が控除対象と押さえる。"
