    "exp1": "未成年者控除は、相続人が18歳未満の場合に相続税の税額から差し引ける税額控除。控除額＝(18歳－相続開始時の年齢)×10万円。年齢は「年」単位で1歳未満は切り捨て。例：15歳3か月→15歳として計算。15歳の場合：(18－15)×10万円＝30万円を税額から直接控除。控除額が相続税額を超える場合は未使用分を扶養義務者（親等）の相続税から控除可。\n\n<svg width=\"300\" height=\"145\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"145\" fill=\"#f0f7e6\" rx=\"8\"/>\n  <text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2d6a2d\">未成年者控除の計算</text>\n  <rect x=\"15\" y=\"28\" width=\"270\" height=\"24\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">（18歳 − 相続時の年齢） × 10万円</text>\n  <text x=\"20\" y=\"68\" font-size=\"11\" fill=\"#333\">例）相続時15歳3か月 → 15歳（切捨て）</text>\n  <text x=\"20\" y=\"85\" font-size=\"11\" fill=\"#333\">（18 − 15）× 10万円</text>\n  <line x1=\"15\" y1=\"93\" x2=\"285\" y2=\"93\" stroke=\"#4caf50\" stroke-width=\"1.5\"/>\n  <text x=\"20\" y=\"112\" font-size=\"12\" font-weight=\"bold\" fill=\"#d32f2f\">控除額 ＝ 3 × 10万円 ＝ 30万円</text>\n  <text x=\"20\" y=\"132\" font-size=\"9\" fill=\"#555\">※税額控除（税額から直接引く）。所得控除ではない。</text>\n</svg>",
    "exp2": "試験では「基準年齢が18歳（2022年4月以降）」「年齢は年単位・1歳未満切捨て」「税額控除（所得控除でない）」「控除しきれない分は扶養義務者から引ける」が問われる。2022年4月の民法改正で成年年齢が20歳→18歳に引き下げられたため、旧基準(20歳)との混同に注意。年齢の切捨て計算例：16歳11か月→16歳として計算→（18－16）×10万円＝20万円控除。未成年者控除は相続税額から直接差し引く「税額控除」であるため、所得控除（課税所得から引く）と比べて節税効果が確実に金額分生じる。",
    "exp3": "「未成年者控除は所得控除」は誤り。所得から引くのではなく、計算された相続税額から直接引く「税額控除」。税額控除の方が節税効果は確実に金額分発生する。また基準の18歳を20歳と混同しないよう注意。「障害者控除の基準年齢（85歳）」と「未成年者控除の基準年齢（18歳）」を混同しないこと——どちらも「（基準年齢－相続時年齢）×万円」という同じ計算式だが、基準年齢と乗じる金額が異なる。",
    "memory": "未成年者控除は「(18歳−相続時年齢)×10万円」の税額控除。年齢は1歳未満切捨て。控除しきれない分は扶養義務者の税額から差し引ける。",
    "svg": "<svg width=\"300\" height=\"145\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"145\" fill=\"#f0f7e6\" rx=\"8\"/>\n  <text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2d6a2d\">未成年者控除の計算</text>\n  <rect x=\"15\" y=\"28\" width=\"270\" height=\"24\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">（18歳 − 相続時の年齢） × 10万円</text>\n  <text x=\"20\" y=\"68\" font-size=\"11\" fill=\"#333\">例）相続時15歳3か月 → 15歳（切捨て）</text>\n  <text x=\"20\" y=\"85\" font-size=\"11\" fill=\"#333\">（18 − 15）× 10万円</text>\n  <line x1=\"15\" y1=\"93\" x2=\"285\" y2=\"93\" stroke=\"#4caf50\" stroke-width=\"1.5\"/>\n  <text x=\"20\" y=\"112\" font-size=\"12\" font-weight=\"bold\" fill=\"#d32f2f\">控除額 ＝ 3 × 10万円 ＝ 30万円</text>\n  <text x=\"20\" y=\"132\" font-size=\"9\" fill=\"#555\">※税額控除（税額から直接引く）。所得控除ではない。</text>\n</svg>"
