    "exp1": "贈与税は、個人から個人への贈与（無償の財産移転）に対して受贈者（もらった側）に課税される国税。法人からの贈与は贈与税でなく所得税が課される。課税方式は原則「暦年課税」と選択できる「相続時精算課税」の2種類。暦年課税の基礎控除は年110万円。贈与を受けた翌年の2月1日〜3月15日に確定申告で申告・納税。",
    "exp2": "試験では「贈与税は受贈者が納税（贈与した側でない）」「法人からの贈与は所得税」「申告期限（翌年2月1日〜3月15日）」「暦年課税と相続時精算課税の選択」が問われる。年110万円以内の贈与は申告・納税不要。110万円超の贈与は翌年の確定申告が必要。贈与税は所得税・消費税とは独立した税目（国税）で、相続税の補完税という位置付け——生前に財産を渡す場合に贈与税、死亡後に渡す場合に相続税が課されることで、生前贈与による相続税回避を防ぐ仕組み。2024年改正で相続前7年以内の贈与が相続財産に加算されるよう持戻し期間が延長された（旧3年→新7年）。\n\n<svg width=\"300\" height=\"145\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"145\" fill=\"#f0f7e6\" rx=\"8\"/>\n  <text x=\"150\" y=\"18\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2d6a2d\">贈与税の2課税方式</text>\n  <rect x=\"10\" y=\"26\" width=\"135\" height=\"68\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"77\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"bold\" fill=\"#1b5e20\">暦年課税（原則）</text>\n  <text x=\"77\" y=\"57\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">基礎控除：年110万円</text>\n  <text x=\"77\" y=\"71\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">超過分に10〜55%</text>\n  <text x=\"77\" y=\"85\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">相続財産への加算あり</text>\n  <rect x=\"155\" y=\"26\" width=\"135\" height=\"68\" fill=\"#fff9c4\" rx=\"4\"/>\n  <text x=\"222\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"bold\" fill=\"#e65100\">相続時精算課税（選択）</text>\n  <text x=\"222\" y=\"57\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">特別控除：累計2,500万円</text>\n  <text x=\"222\" y=\"71\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">超過分に一律20%</text>\n  <text x=\"222\" y=\"85\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">相続時に精算して課税</text>\n  <text x=\"15\" y=\"113\" font-size=\"9\" fill=\"#555\">受贈者が納税（もらう側）。申告は翌年2/1〜3/15。</text>\n  <text x=\"15\" y=\"130\" font-size=\"9\" fill=\"#555\">法人→個人の贈与は贈与税でなく所得税が課される。</text>\n</svg>",
    "exp3": "「親から子への贈与は非課税」は誤り。直系尊属間でも贈与税がかかる。ただし基礎控除110万円以内なら非課税・申告不要。110万円を超えると超過分に課税される。「あげた側」が払うと思いがちだが、納税義務者は「もらった側（受贈者）」。",
    "memory": "贈与税は受贈者（もらう側）が納税。法人からの贈与は所得税。暦年課税と相続時精算課税の2方式。申告期限は翌年2月1日〜3月15日。",
    "svg": "<svg width=\"300\" height=\"145\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"145\" fill=\"#f0f7e6\" rx=\"8\"/>\n  <text x=\"150\" y=\"18\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2d6a2d\">贈与税の2課税方式</text>\n  <rect x=\"10\" y=\"26\" width=\"135\" height=\"68\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"77\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"bold\" fill=\"#1b5e20\">暦年課税（原則）</text>\n  <text x=\"77\" y=\"57\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">基礎控除：年110万円</text>\n  <text x=\"77\" y=\"71\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">超過分に10〜55%</text>\n  <text x=\"77\" y=\"85\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">相続財産への加算あり</text>\n  <rect x=\"155\" y=\"26\" width=\"135\" height=\"68\" fill=\"#fff9c4\" rx=\"4\"/>\n  <text x=\"222\" y=\"42\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"bold\" fill=\"#e65100\">相続時精算課税（選択）</text>\n  <text x=\"222\" y=\"57\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">特別控除：累計2,500万円</text>\n  <text x=\"222\" y=\"71\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">超過分に一律20%</text>\n  <text x=\"222\" y=\"85\" text-anchor=\"middle\" font-size=\"9\" fill=\"#333\">相続時に精算して課税</text>\n  <text x=\"15\" y=\"113\" font-size=\"9\" fill=\"#555\">受贈者が納税（もらう側）。申告は翌年2/1〜3/15。</text>\n  <text x=\"15\" y=\"130\" font-size=\"9\" fill=\"#555\">法人→個人の贈与は贈与税でなく所得税が課される。</text>\n</svg>"
