    "exp1": "暦年課税は、暦年（1月1日〜12月31日）に受けた全ての贈与の合計額から基礎控除110万円を差し引き、残額に税率（10〜55%の超過累進税率）を掛けて贈与税を計算する方式。基礎控除110万円は受贈者1人につき年1回適用。複数の人から合計300万円の贈与を受けても、控除は110万円のみ（190万円に課税）。",
    "exp2": "試験では「基礎控除110万円は受贈者単位（贈与者ごとではない）」「超過累進税率の適用」「一般税率と特例税率の区別（直系尊属から18歳以上受贈者への贈与は特例税率で有利）」が問われる。贈与税の申告・納税は翌年の2月1日〜3月15日。110万円以内なら申告不要。暦年課税の節税活用：毎年110万円以内の贈与を長期間続けることで相続財産を圧縮できる。例えば毎年100万円を10年間贈与すれば合計1,000万円の財産を無税で移転できる（ただし定期贈与とみなされないよう都度贈与契約書を作成する必要あり）。2024年改正で相続前7年以内の暦年贈与は相続財産に持ち戻される（3年超〜7年分は100万円控除後に加算）。\n\n<svg width=\"300\" height=\"145\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"145\" fill=\"#f0f7e6\" rx=\"8\"/>\n  <text x=\"150\" y=\"18\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2d6a2d\">暦年課税の基礎控除（受贈者単位）</text>\n  <rect x=\"15\" y=\"26\" width=\"270\" height=\"24\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"42\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">贈与税 ＝ (年間贈与合計額 − 110万円) × 税率</text>\n  <text x=\"20\" y=\"65\" font-size=\"10\" fill=\"#333\">例）A・B・Cから各100万円の贈与を受けた場合</text>\n  <text x=\"20\" y=\"80\" font-size=\"10\" fill=\"#333\">　　合計 300万円 − 基礎控除 110万円</text>\n  <text x=\"20\" y=\"95\" font-size=\"11\" font-weight=\"bold\" fill=\"#d32f2f\">　　課税額 ＝ 190万円（× 税率）</text>\n  <line x1=\"15\" y1=\"103\" x2=\"285\" y2=\"103\" stroke=\"#4caf50\" stroke-width=\"1.5\"/>\n  <text x=\"20\" y=\"120\" font-size=\"9\" fill=\"#555\">❌「110万円×贈与者数分が控除される」は誤り</text>\n  <text x=\"20\" y=\"135\" font-size=\"9\" fill=\"#555\">✅ 受贈者1人につき年110万円が限度</text>\n</svg>",
    "exp3": "「各贈与者から110万円ずつ非課税で受け取れる」は誤り。基礎控除は受贈者1人につき年110万円が上限。A・B・Cから各100万円をもらっても合計300万円から110万円を控除した190万円に課税される。",
    "memory": "暦年課税の基礎控除110万円は受贈者単位・年1回のみ。複数人から合計300万円もらっても190万円に課税。相続前7年以内の贈与は持ち戻し対象。",
    "svg": "<svg width=\"300\" height=\"145\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"145\" fill=\"#f0f7e6\" rx=\"8\"/>\n  <text x=\"150\" y=\"18\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2d6a2d\">暦年課税の基礎控除（受贈者単位）</text>\n  <rect x=\"15\" y=\"26\" width=\"270\" height=\"24\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"42\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">贈与税 ＝ (年間贈与合計額 − 110万円) × 税率</text>\n  <text x=\"20\" y=\"65\" font-size=\"10\" fill=\"#333\">例）A・B・Cから各100万円の贈与を受けた場合</text>\n  <text x=\"20\" y=\"80\" font-size=\"10\" fill=\"#333\">　　合計 300万円 − 基礎控除 110万円</text>\n  <text x=\"20\" y=\"95\" font-size=\"11\" font-weight=\"bold\" fill=\"#d32f2f\">　　課税額 ＝ 190万円（× 税率）</text>\n  <line x1=\"15\" y1=\"103\" x2=\"285\" y2=\"103\" stroke=\"#4caf50\" stroke-width=\"1.5\"/>\n  <text x=\"20\" y=\"120\" font-size=\"9\" fill=\"#555\">❌「110万円×贈与者数分が控除される」は誤り</text>\n  <text x=\"20\" y=\"135\" font-size=\"9\" fill=\"#555\">✅ 受贈者1人につき年110万円が限度</text>\n</svg>"
