    "exp1": "贈与税の基礎控除は、受贈者（もらう側）1人につき年間110万円。年間の贈与合計額が110万円以内なら贈与税はゼロで確定申告も不要。110万円を1円でも超えると超過分に贈与税が課される。注意点として、毎年110万円の贈与を「定期贈与」の意図で行うと、最初から「複数年分の贈与」とみなされ、その総額に贈与税が課される場合がある（連年贈与の問題）。",
    "exp2": "試験では「110万円の基礎控除は受贈者単位」「110万円以内は申告不要」「定期贈与（連年贈与）とみなされるリスク」が問われる。毎年110万円を贈与する場合、贈与の都度贈与契約書を作成し、異なる金額・時期で贈与するなどの工夫が実務的には推奨される。定期贈与と判断されるのは、最初から「毎年100万円を10年間」という契約がある場合——この場合、初年度に1,000万円の贈与があったとみなされ贈与税が一括課税される。これを避けるには「毎回意思決定して贈与する（定期契約をしない）」ことが重要。",
    "exp3": "「毎年110万円の贈与は絶対に安全」は誤り。贈与者が最初から「毎年100万円ずつ10年間贈与する」と決めていた場合、税務上は最初の年に1,000万円の贈与があったとみなされる可能性（定期贈与）がある。都度の贈与契約書作成が重要。「年110万円以内＝申告不要」は暦年課税の基本ルールだが、「2024年改正で相続前7年以内の贈与は持ち戻し（相続財産への加算）が必要」という新ルールとの組み合わせで考えることが2026年以降の試験・実務では重要。",
    "memory": "贈与税の基礎控除は受贈者1人年110万円まで非課税・申告不要。110万円超えると超過分に課税。毎年同額の定期贈与は総額一括課税リスクあり。都度の契約書作成が重要。",
    "svg": "<svg width=\"300\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\">\n  <rect width=\"300\" height=\"180\" fill=\"#f0f7e6\" rx=\"8\"/>\n  <text x=\"150\" y=\"20\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"bold\" fill=\"#2d6a2d\">贈与税の基礎控除（暦年課税）</text>\n  <rect x=\"15\" y=\"30\" width=\"270\" height=\"24\" fill=\"#c8e6c9\" rx=\"4\"/>\n  <text x=\"150\" y=\"46\" text-anchor=\"middle\" font-size=\"11\" fill=\"#1b5e20\">基礎控除 110万円（受贈者1人・年1回）</text>\n  <!-- 非課税ゾーン -->\n  <rect x=\"15\" y=\"62\" width=\"160\" height=\"30\" fill=\"#81c784\" rx=\"4\"/>\n  <text x=\"95\" y=\"80\" text-anchor=\"middle\" font-size=\"10\" fill=\"white\">110万円以内 → 非課税・申告不要</text>\n  <!-- 課税ゾーン -->\n  <rect x=\"185\" y=\"62\" width=\"100\" height=\"30\" fill=\"#e57373\" rx=\"4\"/>\n  <text x=\"235\" y=\"80\" text-anchor=\"middle\" font-size=\"10\" fill=\"white\">超過分 → 課税</text>\n  <text x=\"150\" y=\"115\" text-anchor=\"middle\" font-size=\"10\" fill=\"#333\">例：年間 150万円の贈与を受けた場合</text>\n  <text x=\"150\" y=\"132\" text-anchor=\"middle\" font-size=\"11\" fill=\"#333\">150万円 − 110万円 ＝ 40万円 に課税</text>\n  <rect x=\"15\" y=\"148\" width=\"270\" height=\"20\" fill=\"#fff9c4\" rx=\"3\"/>\n  <text x=\"150\" y=\"162\" text-anchor=\"middle\" font-size=\"9\" fill=\"#7a5c00\">注意：定期贈与とみなされると総額課税になる場合あり</text>\n</svg>"
