    "exp1": "住宅取得資金の贈与の非課税特例は、18歳以上の受贈者が直系尊属（父母・祖父母等）から住宅取得資金の贈与を受け、一定期間内に住宅を取得・居住した場合に一定額まで非課税になる制度（2026年現在の適用期限・非課税額は確認要）。省エネ性能・耐震性の高い住宅は非課税枠が大きい。暦年課税の110万円基礎控除と併用可能。",
    "exp2": "試験では「直系尊属からの贈与であること」「受贈者の年齢要件（18歳以上）」「住宅の品質要件（省エネ・耐震で枠が異なる）」「適用年限・非課税限度額（時事確認）」が問われる。相続時精算課税との選択適用も可能だが、いずれか有利な方を選ぶ。2026年現在、省エネ等基準適合住宅：1,000万円の非課税枠、それ以外の住宅：500万円の非課税枠（2026年12月31日までの贈与が対象）。暦年課税の基礎控除110万円と併用すると、省エネ住宅なら最大1,110万円まで非課税で贈与を受けられる。",
    "exp3": "「住宅取得資金の贈与なら誰からでも非課税」は誤り。贈与者が直系尊属（父母・祖父母）に限定される。配偶者の親（義父母）からの贈与は対象外（直系尊属ではない）。また受贈者本人が居住する住宅でなければ適用できない。「直系尊属」の定義：自分から見て縦上の血縁（父母・祖父母）——配偶者の親は「姻族」であり直系尊属には含まれない点は試験の定番の誤り選択肢。",
