    "exp3": "「過半数でよい」「法定相続分通りに自動的に決まる」はいずれも誤り。協議不成立の場合は家庭裁判所の調停・審判に進む。遺産分割協議と遺産分割協議書は別概念——協議は口頭でも成立し得るが、実務・法的証明力のために必ず書面化（協議書）する。協議書なしでは不動産登記・預貯金解約等の手続きができない。",
