    "exp3": "「親が死亡したら保険終了」は誤り。保険料払込免除特約があるため継続される点が学資保険の重要な特徴。学資保険の課税は「契約者≠受取人」かどうかで変わる点も試験に出やすい。契約者（親）が死亡し受取人（子）が満期保険金を受け取る場合は一時所得ではなく贈与税の対象になるケースがある。通常の「契約者と受取人が同じ親」のケースでは一時所得扱いとなる。",
