    "exp2": "グロス利回りは計算が簡単で物件比較に使いやすいが、実態の収益性を正確に反映しない点が欠点だ。実際の収益性を見るにはネット利回り（実質利回り）を使う。FP3試験では「グロス＝表面利回り＝諸経費前」「ネット＝実質利回り＝諸経費後」の対比が頻出だ。グロス利回りは「満室想定・諸経費ゼロ」という理想状態での利回りなので、現実の収益性からは乖離することが多い。実際の投資では空室率10〜20%・管理費5〜10%などを見込んでネット利回りを計算する。",
